"""Explain unknown-origin evidence and scoped permissive policies."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1705': ('잠깐 다른 곳을 봤다가 돌아오니 칠판의 7이 9로 바뀌었어요. 바뀐 것은 알지만 누가 고쳤는지는 못 봤어요. 두 가지 정보는 따로 말해야 해요.', '값 변화의 관찰과 값을 바꾼 실행 흐름의 확인을 구별합니다.', '관찰 전7 → 잠시 지연 → 관찰 후9를 그리세요. 변화 확인, 쓴 사람 미확인을 각각 적으세요.', ['KCSAN은 여러 실행 흐름이 같은 메모리를 다룰 때 생기는 충돌을 찾는 도구예요. writer는 값을 쓰는 쪽의 실행 흐름을 뜻해요. unknown origin은 이 쓴 쪽의 정보를 확인하지 못한 경우를 가리켜요.', '원문은 잠시 지연하기 전후의 값은 달라졌지만 다른 충돌 실행 흐름을 관찰하지 못한 경우를 설명해요. stall은 여기서 검사를 위해 잠시 진행을 늦추는 것이에요. 값의 변화는 봤고, 상대가 누구인지는 못 본 상태예요.', '예를 들어 전의 값 old가 7이고 뒤의 값 new가 9라면 달라졌다는 사실은 확인할 수 있어요. 하지만 이 두 숫자만으로 어느 함수의 어느 실행 흐름이 썼는지 알아낼 수는 없어요. unknown이라는 이름을 값도 모른다거나 변화가 없다는 뜻으로 읽으면 안 돼요.', 'kcsan_report_unknown_origin은 이런 경우의 보고 인터페이스예요. ptr는 접근한 메모리 주소, size는 바이트 길이, access_type은 접근 종류, ip는 코드 위치를 전달해요. 알려진 정보를 보고에 남기되 확인하지 못한 상대의 위치를 만들어 내지는 않아요.', '인자에는 old와 new뿐 아니라 mask도 있어요. 마스크는 어떤 비트에 관심을 두는지 나타내는 정보예요. 보고 단계에 값과 관심 비트 정보를 함께 전달하는 것이므로 숫자 하나만 받는 함수가 아니에요. 정확한 표시 방식은 보고 구현을 추가로 읽어야 해요.', 'known origin 경로는 상대 접근 정보를 확보한 경우이고 unknown origin은 상대 정보를 관찰하지 못한 경우예요. 두 보고가 가진 근거의 범위가 달라요. 이 수업은 선언과 설명을 읽는 것이며 실제 지연이나 다른 실행 흐름의 쓰기를 실험한 결과는 아니에요.'], [('unknown origin은 값이 바뀌지 않았다는 뜻인가요?', ['네. 전후 값이 같다는 뜻이에요', '아니요. 값은 바뀌었지만 쓴 실행 흐름을 관찰하지 못했어요'], '정답은 두 번째예요. 칠판의 7이 9로 바뀐 것은 봤지만 누가 바꿨는지는 못 본 상황과 같아요. 모르는 것은 상대의 정보이지 관찰한 값 변화 자체가 아니에요.'), ('이 보고 함수에는 old와 new 외에 mask도 전달하나요?', ['네. 관심 비트에 관한 mask도 받아요', '아니요. 숫자 하나만 받아요'], '정답은 첫 번째예요. 선언 끝에 u64 old, u64 new, u64 mask가 있어요. 관찰한 두 값과 비트 관련 정보를 구별해 전달해요.')]), 'os1706': ('학교 전체 방송 스위치와 한 교실의 소리 조절은 범위가 달라요. 컴퓨터 검사 기능도 전체 설정과 현재 작업의 설정을 나누어 읽어야 해요.', '전역 설정·현재 실행 문맥·추적 기록과 함수 단위 필터를 구별합니다.', '전역 활성화, 현재 문맥 제한, 작업/인터럽트 지연, 추적 기록 보존 네 칸을 만들어 역할을 적으세요.', ['kcsan_enabled는 KCSAN의 전역 활성 상태를 나타내는 변수예요. 전역은 특정 변수 하나나 현재 작업 하나에만 한정된 범위가 아니라 전체 기능에 관련된 범위라는 뜻이에요. 앞에서 배운 현재 문맥의 disable 상태와 구별해야 해요.', '문맥은 지금 어떤 실행 상황에서 일을 하는지를 뜻해요. 전체 기능이 켜져 있어도 현재 문맥에서 검사를 제한하는 조건이 따로 있을 수 있어요. 전역 켜짐만으로 모든 접근이 반드시 검사된다고 결론내리면 안 돼요.', '헤더는 kcsan_udelay_task와 kcsan_udelay_interrupt를 따로 선언해요. task는 작업 실행 쪽, interrupt는 외부 사건 등에 반응하는 인터럽트 처리 쪽이에요. 이 이름들은 두 실행 상황의 지연 설정을 구분해요. 선언만으로 모든 검사에서 정확히 같은 시간을 기다린다고 말할 수는 없어요.', 'kcsan_save_irqtrace와 kcsan_restore_irqtrace는 KCSAN 때문에 바뀐 IRQ 상태 추적 기록을 보존하고 복구하는 인터페이스예요. IRQ는 인터럽트 요청과 관련된 말이고 trace는 추적 기록이에요. 실제 CPU의 인터럽트 허용 상태와 그 상태를 기록한 추적 정보는 같은 것이 아니에요.', 'kcsan_skip_report_debugfs는 주어진 코드 주소가 속한 함수의 보고를 생략할지 판단하는 선언이에요. symbol은 여기서 함수 이름에 대응하는 코드 단위예요. offset은 함수 시작에서 얼마나 떨어진 위치인지를 뜻해요. 원문은 이 위치 차이를 무시한다고 설명해요.', '예를 들어 같은 함수의 시작+4와 시작+12를 주더라도 이 설명은 명령 하나하나를 별도 정책 대상으로 구별하지 않아요. 함수 단위로 읽어야 해요. 이 헤더는 기능의 이름과 계약을 선언한 곳이고 실제 상태 변경이나 보고 제외 구현은 다른 코드에서 확인해야 해요.'], [('전역 kcsan_enabled와 현재 문맥의 검사 제한은 같은 범위인가요?', ['네. 둘 다 현재 변수 하나에만 적용돼요', '아니요. 전체 기능 상태와 현재 실행 상황의 제한은 달라요'], '정답은 두 번째예요. 헤더는 kcsan_enabled를 전역 활성화라고 설명해요. 현재 문맥만 제한하는 기능과 범위를 혼동하면 어느 검사에 영향이 있는지 잘못 판단하게 돼요.'), ('보고 제외 함수의 설명은 같은 함수 안의 위치 차이인 offset을 구별하나요?', ['아니요. offset을 무시한다고 설명해요', '네. 모든 명령 위치마다 반드시 다른 정책이에요'], '정답은 첫 번째예요. 주어진 주소가 속한 함수 symbol을 기준으로 읽어요. 같은 함수 시작+4와 시작+12를 서로 다른 함수인 것처럼 취급한다는 설명이 아니에요.')]), 'os1707': ('경보 소리가 너무 자주 나서 어떤 종류의 알림을 숨겼다고 해 봐요. 알림이 안 들린다는 사실만으로 그 문제가 해결됐다고 할 수는 없어요.', '주소 기반 생략 규칙의 정확한 대상과 안전성의 차이를 이해합니다.', '현재 작업의 flags 주소A와 같은 값이 든 다른 변수 주소B를 그리세요. 주소A 비교와 값 비교는 다르다고 적으세요.', ['permissive.h는 일부 충돌 가능 접근을 검사나 보고 대상에서 생략하는 정책을 모은 파일이에요. 정책을 핵심 검사 코드와 분리해 두면 어떤 경우를 생략하는지 살펴보기 쉬워요. permissive는 여기서 더 허용적인 검사 방침을 뜻해요.', 'CONFIG_KCSAN_PERMISSIVE가 꺼져 있으면 kcsan_ignore_address는 false를 돌려줘요. ignore는 생략한다는 뜻이므로 false는 이 규칙으로 생략하지 않는다는 뜻이에요. false가 곧바로 오류가 있다는 판정은 아니에요.', '설정이 켜져 있을 때 주소 규칙은 ptr == &current->flags예요. current는 지금 실행 중인 작업을 가리키고, ->flags는 그 작업 구조체 안의 flags 항목이에요. &는 그 항목이 있는 주소를 얻어요. ==는 두 주소가 같은지 비교해요.', '따라서 정확히 현재 작업의 flags 주소일 때 이 주소 규칙이 참이 돼요. 다른 작업의 flags, 이름만 flags인 다른 변수, 같은 숫자가 들어 있는 다른 변수까지 이름이나 값으로 찾아 생략하는 규칙이 아니에요. 주소A와 주소B에 둘 다 7이 있어도 A와 B의 위치는 달라요.', '원문은 현재 작업 flags에 대한 충돌 가능 비트 연산이 너무 흔해서 당장은 무시한다고 설명해요. 하지만 파일 첫 주석은 이런 규칙이 해당 충돌을 일반적으로 안전하다고 뜻하지는 않는다고 강조해요. 자주 발생한다는 것과 올바른 동기화라는 것은 다르기 때문이에요.', '그러므로 생략 규칙에 걸렸다고 잠금을 없애도 된다고 판단하면 안 돼요. 보고를 줄이는 방침은 실행 순서를 맞추거나 데이터를 보호하는 동작을 대신하지 않아요. 코드가 실제로 안전한지는 접근 방식과 보호 규칙을 별도로 검토해야 해요.'], [('이 주소 규칙은 flags라는 이름의 변수를 모두 찾아 생략하나요?', ['네. 모든 작업과 모든 변수의 flags를 생략해요', '아니요. ptr가 정확히 &current->flags와 같은지 비교해요'], '정답은 두 번째예요. 본문은 이름 검색이나 값 비교가 아니라 주소 비교예요. 다른 작업의 flags나 같은 값이 든 다른 변수는 이 정확한 주소와 다를 수 있어요.'), ('이 정책으로 보고가 생략되면 충돌이 일반적으로 안전하다는 증거인가요?', ['아니요. 알림 생략과 실제 안전성은 달라요', '네. 잠금이 필요 없다는 증거예요'], '정답은 첫 번째예요. 파일 첫 주석도 일반적인 안전성을 뜻하지 않는다고 말해요. 검사가 조용해졌다는 사실이 잘못된 동시 접근을 고쳐 주지는 않아요.')]), 'os1708': ('할인 대상인지 보려면 먼저 종류와 크기 조건을 통과해야 해요. 뒤의 조건 하나가 맞더라도 앞에서 제외됐으면 할인 대상이 아니에요. 이 생략 규칙도 조건을 순서대로 확인해요.', '접근 종류와 길이 조건을 먼저 확인해야 하는 이유를 이해합니다.', 'long이 8바이트인 예에서 type0·길이8, type1·길이8, type0·길이9를 비교하세요. 첫 경우만 다음 조건으로 간다고 적으세요.', ['kcsan_ignore_data_race는 접근 종류와 값 변화 모양을 보고 생략할지 판단하는 도우미예요. 먼저 CONFIG_KCSAN_PERMISSIVE가 켜져 있어야 해요. 꺼져 있으면 바로 false라서 이 정책으로 생략하지 않아요.', '그 다음 if (type || size > sizeof(long))이면 false로 돌아가요. ||는 둘 중 하나라도 참이면 된다는 뜻이에요. type은 접근 종류 표시이고 size는 접근 바이트 수예요. sizeof(long)은 이 구성에서 long 정수가 차지하는 바이트 수예요.', '대상은 type=0인 plain read, 즉 특별한 접근 표시가 없는 일반 읽기예요. WRITE=1, 읽고 쓰는 복합 표시3, ATOMIC=4, ASSERT=8처럼 type이 0이 아니면 여기서 제외돼요. 표시 비트 중 하나라도 켜져 있는지 먼저 보는 것이에요.', '길이도 long 크기 이하여야 해요. long이 8바이트인 예에서는 길이8은 이 크기 조건을 통과하지만 길이9는 제외돼요. long이 4바이트인 구성이라면 경계도 4로 바뀌어요. 모든 환경에서 long이 8이라고 외우면 안 돼요.', '앞 조건을 통과해야 뒤에서 몇 비트가 바뀌었는지와 예외 규칙을 살펴요. 예를 들어 type0·길이8이 통과했다는 것만으로 바로 생략이 확정되는 것은 아니에요. 반대로 type1이거나 길이9이면 한 비트만 변했더라도 이 정책은 앞에서 false로 돌아가요. 복합 읽기·쓰기 충돌도 계속 보고 대상으로 남기려는 구분이에요.', '이 작은 함수의 크기 비교만 보면 size=0도 통과할 수 있어요. 하지만 실제 check_access는 길이0을 먼저 제외해요. 부분 조건을 통과하는 것과 전체 검사 흐름에서 실제 호출되는 것은 구별해야 해요. 또 생략하지 않는다는 false도 다른 모든 보고 조건을 통과했다는 뜻은 아니에요.'], [('type에 WRITE 표시가 있으면 뒤의 값 변화 생략 규칙을 적용하나요?', ['네. 모든 쓰기를 생략해요', '아니요. type이 0이 아니라서 먼저 false로 돌아가요'], '정답은 두 번째예요. 본문은 type || size>sizeof(long)을 먼저 확인해요. 이 정책의 대상은 type0인 일반 읽기이므로 쓰기는 앞에서 제외돼요.'), ('길이가 sizeof(long)+1인데 한 비트만 바뀌었어요. 이 정책이 생략하나요?', ['아니요. 먼저 길이 조건에서 제외돼요', '네. 바뀐 비트 수만 보면 돼요'], '정답은 첫 번째예요. 길이 제한은 변화 비트 수를 세기 전에 적용돼요. long이 8바이트이면 9바이트 접근은 다음 생략 조건까지 가지 않아요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_422.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
